-- Private field-sales CRM for the Dukenim platform owner.
-- No tenant or merchant can read this prospecting database.
create table public.field_sales_zones (
  id text primary key check (id ~ '^Z[0-9]+$'),
  name text not null,
  road_boundaries text not null,
  west numeric not null,
  east numeric not null,
  south numeric not null,
  north numeric not null,
  sort_order integer not null default 0,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  check (west < east and south < north)
);

create table public.field_sales_leads (
  id uuid primary key default gen_random_uuid(),
  external_source text not null default '2gis',
  external_id text,
  zone_id text not null references public.field_sales_zones(id) on update cascade,
  name text not null check (char_length(name) between 1 and 240),
  address text not null default '',
  segment text not null default 'Другое',
  subsegment text not null default '',
  longitude numeric,
  latitude numeric,
  phone text,
  instagram_url text,
  website_url text,
  whatsapp_url text,
  map_url text,
  schedule text,
  rating numeric,
  review_count integer not null default 0 check (review_count >= 0),
  branch_count integer not null default 1 check (branch_count >= 0),
  priority_score integer not null default 0 check (priority_score between 0 and 100),
  priority text not null default 'B — следующий приоритет',
  status text not null default 'new' check (status in ('new','planned','contacted','negotiating','demo','follow_up','won','lost','do_not_contact')),
  contact_name text,
  contact_role text,
  contact_phone text,
  notes text not null default '',
  next_action text not null default '',
  reminder_at timestamptz,
  last_visit_at timestamptz,
  assigned_to uuid references auth.users(id) on delete set null,
  route_day date,
  route_position integer check (route_position is null or route_position > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (external_source, external_id)
);

create table public.field_sales_activities (
  id uuid primary key default gen_random_uuid(),
  lead_id uuid not null references public.field_sales_leads(id) on delete cascade,
  actor_id uuid references auth.users(id) on delete set null,
  event_type text not null check (event_type in ('created','status_changed','note','visit','reminder','route_planned')),
  previous_status text,
  next_status text,
  note text,
  created_at timestamptz not null default now()
);

create index field_sales_leads_zone_status_idx on public.field_sales_leads(zone_id,status);
create index field_sales_leads_reminder_idx on public.field_sales_leads(reminder_at) where reminder_at is not null;
create index field_sales_leads_route_idx on public.field_sales_leads(route_day,route_position) where route_day is not null;
create index field_sales_leads_segment_idx on public.field_sales_leads(zone_id,segment);
create index field_sales_activities_lead_idx on public.field_sales_activities(lead_id,created_at desc);

create function public.touch_field_sales_lead()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at = now();
  return new;
end $$;

create trigger touch_field_sales_lead_before_update
before update on public.field_sales_leads
for each row execute function public.touch_field_sales_lead();

alter table public.field_sales_zones enable row level security;
alter table public.field_sales_leads enable row level security;
alter table public.field_sales_activities enable row level security;

revoke all on table public.field_sales_zones from public, anon, authenticated;
revoke all on table public.field_sales_leads from public, anon, authenticated;
revoke all on table public.field_sales_activities from public, anon, authenticated;
grant select, insert, update, delete on table public.field_sales_zones to authenticated;
grant select, insert, update, delete on table public.field_sales_leads to authenticated;
grant select, insert on table public.field_sales_activities to authenticated;

create policy field_sales_zones_superadmin_select on public.field_sales_zones for select to authenticated using (public.is_superadmin());
create policy field_sales_zones_superadmin_insert on public.field_sales_zones for insert to authenticated with check (public.is_superadmin());
create policy field_sales_zones_superadmin_update on public.field_sales_zones for update to authenticated using (public.is_superadmin()) with check (public.is_superadmin());
create policy field_sales_zones_superadmin_delete on public.field_sales_zones for delete to authenticated using (public.is_superadmin());

create policy field_sales_leads_superadmin_select on public.field_sales_leads for select to authenticated using (public.is_superadmin());
create policy field_sales_leads_superadmin_insert on public.field_sales_leads for insert to authenticated with check (public.is_superadmin());
create policy field_sales_leads_superadmin_update on public.field_sales_leads for update to authenticated using (public.is_superadmin()) with check (public.is_superadmin());
create policy field_sales_leads_superadmin_delete on public.field_sales_leads for delete to authenticated using (public.is_superadmin());

create policy field_sales_activities_superadmin_select on public.field_sales_activities for select to authenticated using (public.is_superadmin());
create policy field_sales_activities_superadmin_insert on public.field_sales_activities for insert to authenticated with check (public.is_superadmin());

create function public.update_field_sales_lead(
  p_lead uuid,
  p_status text,
  p_contact_name text,
  p_contact_role text,
  p_contact_phone text,
  p_phone text,
  p_instagram_url text,
  p_website_url text,
  p_notes text,
  p_next_action text,
  p_reminder_at timestamptz,
  p_mark_visit boolean default false
) returns boolean
language plpgsql security invoker set search_path = '' as $$
declare before_row public.field_sales_leads;
begin
  if not public.is_superadmin() then raise exception 'Access denied' using errcode='42501'; end if;
  if p_status not in ('new','planned','contacted','negotiating','demo','follow_up','won','lost','do_not_contact') then
    raise exception 'Invalid status' using errcode='22023';
  end if;
  select * into before_row from public.field_sales_leads where id=p_lead for update;
  if before_row.id is null then return false; end if;
  update public.field_sales_leads set
    status=p_status, contact_name=nullif(trim(p_contact_name),''), contact_role=nullif(trim(p_contact_role),''),
    contact_phone=nullif(trim(p_contact_phone),''), phone=nullif(trim(p_phone),''),
    instagram_url=nullif(trim(p_instagram_url),''), website_url=nullif(trim(p_website_url),''),
    notes=left(coalesce(p_notes,''),10000), next_action=left(coalesce(p_next_action,''),1000),
    reminder_at=p_reminder_at, last_visit_at=case when p_mark_visit then now() else last_visit_at end
  where id=p_lead;
  insert into public.field_sales_activities(lead_id,actor_id,event_type,previous_status,next_status,note)
  values(p_lead,auth.uid(),case when before_row.status<>p_status then 'status_changed' when p_mark_visit then 'visit' else 'note' end,
    before_row.status,p_status,nullif(left(coalesce(p_notes,''),1000),''));
  return true;
end $$;

create function public.plan_field_sales_route(p_zone text,p_day date,p_leads uuid[])
returns integer language plpgsql security invoker set search_path = '' as $$
declare changed integer;
begin
  if not public.is_superadmin() then raise exception 'Access denied' using errcode='42501'; end if;
  if p_day is null or cardinality(p_leads) < 1 or cardinality(p_leads) > 30 then
    raise exception 'Invalid route' using errcode='22023';
  end if;
  update public.field_sales_leads set route_day=null,route_position=null,status=case when status='planned' then 'new' else status end
    where zone_id=p_zone and route_day=p_day;
  update public.field_sales_leads lead set route_day=p_day,route_position=route.position,
    status=case when lead.status='new' then 'planned' else lead.status end
  from unnest(p_leads) with ordinality as route(id,position)
  where lead.id=route.id and lead.zone_id=p_zone;
  get diagnostics changed=row_count;
  insert into public.field_sales_activities(lead_id,actor_id,event_type,note)
    select id,auth.uid(),'route_planned','Маршрут на '||p_day::text from public.field_sales_leads
    where zone_id=p_zone and route_day=p_day;
  return changed;
end $$;

revoke all on function public.update_field_sales_lead(uuid,text,text,text,text,text,text,text,text,text,timestamptz,boolean) from public,anon;
grant execute on function public.update_field_sales_lead(uuid,text,text,text,text,text,text,text,text,text,timestamptz,boolean) to authenticated;
revoke all on function public.plan_field_sales_route(text,date,uuid[]) from public,anon;
grant execute on function public.plan_field_sales_route(text,date,uuid[]) to authenticated;

